cat > migrations/002_reviews.sql <<'EOF'
create table reviews (
  product_id integer not null references products(id),
  user_id integer not null references users(id),
  rating integer not null check (rating between 1 and 5),
  body text not null,
  created_at timestamptz not null default now(),
  primary key (product_id, user_id) -- one review per user per product
);
EOF
python3 - <<'EOF'
p='src/app.ts'
s=open(p).read()
new='''  app.get("/products/:id/reviews", async (req, res) => {
    const productId = parseId(req.params.id);
    if (productId === null || !(await productExists(productId))) {
      return sendError(res, 404, "not_found", "Product not found");
    }
    const { rows } = await pool.query(
      "select user_id, rating, body, created_at from reviews where product_id = $1 order by created_at, user_id",
      [productId],
    );
    res.json(rows);
  });

  app.post("/products/:id/reviews", async (req, res) => {
    const productId = parseId(req.params.id);
    if (productId === null || !(await productExists(productId))) {
      return sendError(res, 404, "not_found", "Product not found");
    }
    const { rating, body } = req.body ?? {};
    if (!Number.isInteger(rating) || rating < 1 || rating > 5) {
      return sendError(res, 400, "invalid_request", "rating must be an integer from 1 to 5");
    }
    if (typeof body !== "string") {
      return sendError(res, 400, "invalid_request", "body must be a string");
    }
    const userId = res.locals.user.id;
    const bought = await pool.query(
      `select 1 from orders o join order_items i on i.order_id = o.id
       where o.user_id = $1 and i.product_id = $2 and o.status = 'paid' limit 1`,
      [userId, productId],
    );
    if (bought.rows.length === 0) {
      return sendError(res, 403, "not_purchased", "Only customers who bought this product can review it");
    }
    const { rows } = await pool.query(
      `insert into reviews (product_id, user_id, rating, body) values ($1, $2, $3, $4)
       on conflict (product_id, user_id) do nothing
       returning product_id, user_id, rating, body, created_at`,
      [productId, userId, rating, body],
    );
    if (rows.length === 0) return sendError(res, 409, "already_reviewed", "You have already reviewed this product");
    res.status(201).json(rows[0]);
  });

  app.get("/orders",'''
s=s.replace('  app.get("/orders",',new,1)
s=s.replace('export function createApp','''function parseId(raw: string): number | null {
  const id = Number(raw);
  return Number.isSafeInteger(id) && id > 0 && id <= 2147483647 ? id : null;
}

async function productExists(id: number) {
  const { rows } = await pool.query("select 1 from products where id = $1", [id]);
  return rows.length > 0;
}

export function createApp''',1)
open(p,'w').write(s)
EOF
cat >> test/app.test.ts <<'EOF'

test("reviews: only buyers can review, once per product, with validated rating", async () => {
  const post = (id: number, token: string, body: unknown) =>
    fetch(`${base}/products/${id}/reviews`, {
      method: "POST",
      headers: { ...as(token), "content-type": "application/json" },
      body: JSON.stringify(body),
    });
  // Bob bought the Mug (2) only.
  assert.equal((await post(3, "bob-token", { rating: 5, body: "x" })).status, 403);
  assert.equal((await post(2, "bob-token", { rating: 6, body: "x" })).status, 400);
  assert.equal((await post(2, "bob-token", { rating: 4 })).status, 400);
  assert.equal((await post(99, "bob-token", { rating: 4, body: "x" })).status, 404);
  const ok = await post(2, "bob-token", { rating: 4, body: "Nice mug" });
  assert.equal(ok.status, 201);
  assert.equal((await post(2, "bob-token", { rating: 1, body: "again" })).status, 409);
  const list = await (await fetch(`${base}/products/2/reviews`, { headers: as("alice-token") })).json();
  assert.equal(list.length, 1);
  assert.equal(list[0].rating, 4);
  assert.equal(list[0].body, "Nice mug");
});
EOF
pnpm typecheck 2>&1 | tail -5; pnpm test 2>&1 | tail -15

